"""Sum up 21 November 2026's world news in one image.

The entry image is a 1024x1024 newspaper-style summary of Saturday
21 November 2026, covering Russia's strikes on Ukraine and missiles
landing in Poland, the AI stock sell-off, the ICJ genocide ruling on
Myanmar / the Rohingya, the COP31 deadlock, the UK-EU post-Brexit
deal, and a pancreatic-cancer trial breakthrough.

The image is embedded in this file as base64 (see IMAGE_B64), so the
entry is a single self-contained text file with no binary asset to
carry. This program does one thing, deterministically and with no
network access: it decodes the embedded image and writes it to
``/output/entry.png``. Running it
twice writes exactly the same bytes, because the embedded data never
changes and no timestamp, random value, or network call is involved.

Usage:
    python3 main.py
"""

import base64
import hashlib
import struct
import sys
from pathlib import Path

# Base64 of the 1024x1024 PNG entry image (489265 bytes).
# Filled in by the build step from the image file; one long line.
IMAGE_B64 = ""

OUTPUT = Path("/output/entry.png")

EXPECTED_WIDTH = 1024
EXPECTED_HEIGHT = 1024
MAX_BYTES = 1024 * 1024


def check_png(data):
    """Check the PNG header and return (width, height, size)."""
    if len(data) < 33 or data[:8] != b"\x89PNG\r\n\x1a\n":
        raise ValueError("decoded data is not a PNG file")
    width, height = struct.unpack(">II", data[16:24])
    return width, height, len(data)


def main():
    if not IMAGE_B64:
        print("embedded image is missing", file=sys.stderr)
        return 1
    data = base64.b64decode(IMAGE_B64)
    width, height, size = check_png(data)
    if (width, height) != (EXPECTED_WIDTH, EXPECTED_HEIGHT):
        print(
            f"unexpected image size: {width}x{height}, "
            f"expected {EXPECTED_WIDTH}x{EXPECTED_HEIGHT}",
            file=sys.stderr,
        )
        return 1
    if size > MAX_BYTES:
        print(f"image too large: {size} bytes, max {MAX_BYTES}", file=sys.stderr)
        return 1
    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    OUTPUT.write_bytes(data)
    digest = hashlib.sha256(OUTPUT.read_bytes()).hexdigest()
    print(f"Wrote {OUTPUT} ({size} bytes, sha256={digest})")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
